class Solution {
public:
    vector<string> findItinerary(vector<vector<string>>& tickets) {
        unordered_map<string, vector<string>> graph;
        for (vector<string>& t : tickets) graph[t[0]].push_back(t[1]);
        for (auto& kv : graph) sort(kv.second.begin(), kv.second.end(), greater<string>());
        path.clear();
        dfs(graph, "JFK");
        reverse(path.begin(), path.end());
        return path;
    }
    vector<string> path;
    void dfs(unordered_map<string, vector<string>>& graph, const string& cur) {
        while (true) {
            auto it = graph.find(cur);
            if (it == graph.end() || it->second.empty()) break;
            string nxt = it->second.back();
            it->second.pop_back();
            dfs(graph, nxt);
        }
        path.push_back(cur);
    }
};

