    int eraseOverlapIntervals(vector<vector<int>>& intervals) {
        sort(intervals.begin(), intervals.end(), [](const vector<int>& a, const vector<int>& b) {
            return a[1] < b[1];
        });
        int removed = 0, end = 0;
        bool has = false;
        for (vector<int>& iv : intervals) {
            if (!has || iv[0] >= end) {
                end = iv[1];
                has = true;
            } else {
                removed++;
            }
        }
        return removed;
    }
};

