    if (v.empty() || v[0] == "null") return nullptr;
    TreeNode *root = new TreeNode(stoi(v[0]));
    queue<TreeNode *> q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < v.size()) {
        TreeNode *cur = q.front();
        q.pop();
        if (i < v.size()) {
            if (v[i] != "null") {
                cur->left = new TreeNode(stoi(v[i]));
                q.push(cur->left);
            }
            i++;
        }
        if (i < v.size()) {
            if (v[i] != "null") {
                cur->right = new TreeNode(stoi(v[i]));
                q.push(cur->right);
